public class PackageDirectoryMapper {

    public static String toDirectory(String packageName) {
        if (packageName == null || packageName.isEmpty()) {
            return "";
        }
        return packageName.replace('.', '/');
    }

    public static String toPackage(String directory) {
        if (directory == null) {
            return "";
        }
        String trimmed = directory;
        while (trimmed.startsWith("/")) {
            trimmed = trimmed.substring(1);
        }
        while (trimmed.endsWith("/")) {
            trimmed = trimmed.substring(0, trimmed.length() - 1);
        }
        return trimmed.replace('/', '.');
    }

    public static String sourcePathFor(String packageName, String className) {
        String directory = toDirectory(packageName);
        if (directory.isEmpty()) {
            return className + ".java";
        }
        return directory + "/" + className + ".java";
    }
}
